/* Product-form enhancement only; the shared CartDrawer owns cart mutations and reconciliation. */
(() => {
  if (!window.customElements || !window.MutationObserver || customElements.get('equipro-product-form')) return;
  // Keep acceptance/uncertainty across a section reconnect for this document only.
  const operations = new Map();
  customElements.define('equipro-product-form', class extends HTMLElement {
    constructor() {
      super();
      this.inFlight = false;
      this.submit = this.submit.bind(this);
      this.recover = this.recover.bind(this);
      this.checked = this.checked.bind(this);
      this.onGlobalRetry = event => {
        const retry = document.getElementById('CartFeedbackRetry');
        if (this.operation.awaitingRecovery && event.target.closest('#CartFeedbackRetry') && document.activeElement === retry) {
          this.globalRetryRestore?.();
          this.globalRetryRestore = this.rememberFocus(true);
        }
      };
      this.onReconciled = () => {
        this.operation.reconciled = true;
        this.operation.awaitingRecovery = false;
        if (this.operation.kind === 'accepted') this.operation.kind = 'confirmed';
        // The shared controller releases its pending lock after dispatching this event.
        clearTimeout(this.syncTimer);
        this.syncTimer = setTimeout(() => { if (this.bound) this.sync(); }, 0);
      };
    }

    connectedCallback() {
      if (this.bound) return;
      const root = this.closest('.product-page');
      this.form = this.querySelector('form');
      this.button = this.form?.querySelector('[type="submit"]');
      const map = root && [...document.querySelectorAll('script[type="application/json"][data-quote-root]')].find(script => script.dataset.quoteRoot === root.id);
      if (!this.form || !this.button || !map || this.dataset.ajaxEligible !== 'true') return;
      try { this.variants = JSON.parse(map.textContent); } catch { return; }
      if (!Array.isArray(this.variants)) return;
      if (this.displayVariant === undefined) this.displayVariant = this.variants.find(item => String(item.id) === map.dataset.quoteInitialVariantId);
      const key = root.id + ':' + map.id;
      if (!operations.has(key)) operations.set(key, {kind:'idle', attempted:false, reconciled:false});
      this.operation = operations.get(key);
      this.status = this.querySelector('[data-product-status]');
      this.error = this.querySelector('[data-product-error]');
      this.actions = this.querySelector('[data-product-actions]');
      this.retry = this.querySelector('[data-product-retry]');
      this.acknowledge = this.querySelector('[data-product-checked]');
      if (!this.status || !this.error || !this.actions || !this.retry || !this.acknowledge) return;
      this.bound = true;
      this.button.classList.add('js-add-to-cart-btn');
      this.form.addEventListener('submit', this.submit);
      this.retry.addEventListener('click', this.recover);
      this.acknowledge.addEventListener('click', this.checked);
      document.addEventListener('cart:reconciled', this.onReconciled);
      document.addEventListener('click', this.onGlobalRetry, true);
      // Other callers use the same shared lock. Do not let their finally block
      // re-enable an invalid variant or an unresolved product-form submission.
      this.observer = new MutationObserver(() => {
        this.sync();
        if (this.globalRetryRestore && !this.cart()?.pending) {
          const restore = this.globalRetryRestore;
          this.globalRetryRestore = null;
          restore();
        }
      });
      this.observer.observe(this.button, {attributes:true, attributeFilter:['disabled']});
      const sharedRetry = document.getElementById('CartFeedbackRetry');
      if (sharedRetry) this.observer.observe(sharedRetry, {attributes:true, attributeFilter:['disabled']});
      this.sync();
    }

    disconnectedCallback() {
      if (!this.bound) return;
      this.bound = false;
      this.form.removeEventListener('submit', this.submit);
      this.retry.removeEventListener('click', this.recover);
      this.acknowledge.removeEventListener('click', this.checked);
      document.removeEventListener('cart:reconciled', this.onReconciled);
      document.removeEventListener('click', this.onGlobalRetry, true);
      this.globalRetryRestore?.();
      this.globalRetryRestore = null;
      this.observer.disconnect();
      clearTimeout(this.syncTimer);
    }

    cart() {
      const cart = window.cartDrawer;
      return ['run','request','refreshDrawer'].every(method => typeof cart?.[method] === 'function') ? cart : null;
    }

    variant() {
      const id = this.form.querySelector('[name="id"]')?.value;
      return this.variants.find(item => String(item.id) === id);
    }

    sync(selectedVariant) {
      if (!this.bound) return;
      if (selectedVariant !== undefined) this.displayVariant = selectedVariant;
      const cart = this.cart(), variant = this.variant(), op = this.operation;
      const displayVariant = variant || this.displayVariant;
      const blocked = !variant?.available || !variant?.purchasable || this.inFlight || cart?.pending || cart?.unsynced ||
        ['accepted','uncertain'].includes(op.kind) || ((!cart || typeof FormData !== 'function') && op.attempted);
      if (this.button.disabled !== Boolean(blocked)) this.button.disabled = Boolean(blocked);
      if (this.inFlight) {
        this.button.textContent = this.dataset.adding;
        this.button.setAttribute('aria-busy','true');
      } else {
        this.button.removeAttribute('aria-busy');
        this.button.textContent = !displayVariant ? this.dataset.invalid : !displayVariant.purchasable ? this.dataset.unavailable :
          !displayVariant.available ? this.dataset.soldout : this.dataset.addLabel;
      }
      let message = '';
      if (this.inFlight && op.kind === 'submitting') message = this.dataset.adding;
      else if (op.kind === 'confirmed') message = this.dataset.added.replace('__VARIANT__', op.label);
      else if (op.kind === 'accepted') message = this.dataset.accepted;
      const error = op.kind === 'uncertain' ? [this.dataset.uncertain, op.error].filter(Boolean).join(' ') : op.error || '';
      if (this.status.textContent !== message) this.status.textContent = message;
      if (this.error.textContent !== error) this.error.textContent = error;
      this.error.hidden = !error;
      this.actions.hidden = !message && !error;
      this.retry.hidden = !cart?.unsynced && !['accepted','uncertain'].includes(op.kind);
      this.retry.disabled = Boolean(this.inFlight || cart?.pending || !cart);
      this.acknowledge.hidden = op.kind !== 'uncertain' || !op.reconciled || Boolean(cart?.unsynced) || !cart;
      this.acknowledge.disabled = Boolean(this.inFlight || cart?.pending);
      this.classList.toggle('has-feedback', Boolean(message || error));
    }

    rememberFocus(sharedRetry = false) {
      const trigger = document.activeElement;
      if (!sharedRetry && !this.contains(trigger)) return () => {};
      let moved = false;
      const watch = event => { if (event.target !== trigger && event.target !== document.body) moved = true; };
      document.addEventListener('focusin', watch);
      return () => {
        document.removeEventListener('focusin', watch);
        if (moved || !this.isConnected || document.querySelector('#CartDrawer.is-open') ||
            (document.activeElement !== trigger && document.activeElement !== document.body)) return;
        const usable = element => element && !element.disabled && !element.closest('[hidden], [inert]');
        const target = usable(trigger) ? trigger : usable(this.button) ? this.button : usable(this.retry) ? this.retry : null;
        target?.focus({preventScroll:true});
      };
    }

    payload(event) {
      // Snapshot before either the local or shared controller disables a control.
      const data = event.submitter ? new FormData(this.form, event.submitter) : new FormData(this.form);
      const ids = data.getAll('id'), quantities = data.getAll('quantity');
      const variant = this.variant(), quantity = Number(quantities[0]);
      const rule = variant?.quantity_rule || {min:1,increment:1,max:null};
      if (ids.length !== 1 || !/^\d+$/.test(ids[0]) || !variant?.available || !variant.purchasable ||
          quantities.length !== 1 || !/^\d+$/.test(quantities[0]) || !Number.isSafeInteger(quantity) || quantity < rule.min ||
          (rule.max !== null && quantity > rule.max) || (quantity - rule.min) % rule.increment !== 0 ||
          [...this.form.querySelectorAll('.product-variant-selector')].some(select => variant.options[Number(select.dataset.optionIndex)] !== select.value) ||
          !this.form.checkValidity()) throw new Error(this.dataset.invalid);
      return {data, variant, label: variant.title === 'Default Title' ? this.dataset.productLabel : this.dataset.productLabel + ' — ' + variant.title};
    }

    async submit(event) {
      if (event.defaultPrevented) return;
      const cart = this.cart(), op = this.operation;
      if (this.inFlight || ['accepted','uncertain'].includes(op.kind) || cart?.pending || cart?.unsynced || ((!cart || typeof FormData !== 'function') && op.attempted)) {
        event.preventDefault(); this.sync(); return;
      }
      // Native fallback is allowed only before an AJAX attempt, never after one.
      if (!cart || typeof FormData !== 'function') return;
      event.preventDefault();
      let snapshot;
      try { snapshot = this.payload(event); }
      catch (error) { op.kind = 'rejected'; op.error = error.message; this.sync(); return; }
      const restoreFocus = this.rememberFocus();
      Object.assign(op, {kind:'submitting', attempted:true, reconciled:false, awaitingRecovery:false, label:snapshot.label, error:''});
      this.inFlight = true; this.sync();
      try {
        await cart.run(async () => {
          try {
            const data = await cart.request(window.Shopify.routes.root + 'cart/add.js', {method:'POST', body:snapshot.data});
            const items = Array.isArray(data.items) ? data.items : [data];
            if (items.length !== 1 || String(items[0].variant_id ?? items[0].id) !== String(snapshot.variant.id) ||
                !Number.isSafeInteger(items[0].quantity) || items[0].quantity < 1) throw new Error(this.dataset.requestError);
            op.kind = 'accepted';
          } catch (error) {
            const rejected = Number.isInteger(error.status) && error.status >= 400 && error.status < 500 && error.status !== 408;
            op.kind = rejected ? 'rejected' : 'uncertain';
            op.error = error.message;
            throw error;
          }
          await cart.refreshDrawer();
        });
      } finally {
        this.inFlight = false;
        op.awaitingRecovery = cart.unsynced;
        if (op.kind === 'accepted' && !cart.unsynced) op.kind = 'confirmed';
        if (op.kind === 'confirmed' && !cart.unsynced && !cart.pending) cart.feedback?.('');
        this.sync(); restoreFocus();
      }
    }

    async recover() {
      const cart = this.cart();
      if (!cart || this.inFlight || cart.pending) return;
      const restoreFocus = this.rememberFocus();
      this.inFlight = true; this.sync();
      try { await cart.run(() => cart.refreshDrawer(), true); }
      finally { this.inFlight = false; this.sync(); restoreFocus(); }
    }

    checked() {
      const cart = this.cart();
      if (!cart || cart.pending || cart.unsynced || this.inFlight || this.operation.kind !== 'uncertain' || !this.operation.reconciled) return;
      Object.assign(this.operation, {kind:'idle', error:''});
      this.sync();
      this.button.focus({preventScroll:true});
    }
  });
})();

(() => {
  const initialize = () => {
    const modal = document.getElementById('QuoteModal');
    if (!modal || modal.dataset.quoteReady) return;
    modal.dataset.quoteReady = 'true';
    const form = modal.querySelector('#QuoteForm');
    const field = name => form.elements.namedItem(`contact[${name}]`);
    const results = [...modal.querySelectorAll('[data-quote-result]')];
    const storageKey = 'equipro.quote.pending';
    let returnFocus;
    let contextInvalid = false;
    const contextError = modal.querySelector('#QuoteVariantError');
    let previousOverflow;
    let inertElements = [];
    let pending = null;
    let storageAvailable = true;
    try { pending = JSON.parse(sessionStorage.getItem(storageKey)); } catch { storageAvailable = false; }

    const clearPending = () => {
      try { sessionStorage.removeItem(storageKey); } catch {}
    };
    const clearResult = () => {
      results.forEach(result => { result.hidden = true; });
      field('email').removeAttribute('aria-invalid');
      field('email').removeAttribute('aria-describedby');
    };
    const preview = () => {
      document.getElementById('QuoteProductDisplay').textContent = field('Requested_Product').value || 'General Equipment Inquiry';
      document.getElementById('QuoteVariantDisplay').textContent = [field('Variant').value, field('SKU').value].filter(Boolean).join(' / ');
    };
    const captureProduct = opener => {
      for (const name of ['Product_ID', 'Variant_ID', 'Requested_Product', 'Variant', 'SKU']) field(name).value = '';
      field('Quantity').value = '1';
      contextInvalid = false;
      if (contextError) contextError.hidden = true;
      form.querySelector('[type="submit"]').disabled = false;
      if (!opener.hasAttribute('data-quote-general')) {
        const source = document.querySelector('[data-quote-product-id]');
        if (source) {
          const productInput = [...document.querySelectorAll('form input[name="product-id"]')].find(input => input.value === source.dataset.quoteProductId);
          const candidateRoot = source.dataset.quoteRoot ? document.getElementById(source.dataset.quoteRoot) : productInput?.form;
          const root = productInput && candidateRoot?.contains(productInput) ? candidateRoot : null;
          const variantInput = root?.querySelector('input[name="id"], select[name="id"]');
          const quantityInput = root?.querySelector('[name="quantity"]');
          let variants = [];
          try {
            const parsed = JSON.parse(source.textContent);
            if (Array.isArray(parsed)) variants = parsed.filter(item => item && /^\d+$/.test(String(item.id)));
          } catch {}
          // Quote identity follows real selected options, never purchase eligibility.
          // Missing or ambiguous context must not fall back to an initial variant.
          const selectors = root ? [...root.querySelectorAll('.product-variant-selector[data-option-index]')] : [];
          let variant;
          if (root && selectors.length) {
            const indexes = selectors.map(select => Number(select.dataset.optionIndex));
            const valid = indexes.every(index => Number.isInteger(index) && index >= 0 && index < 3) &&
              new Set(indexes).size === indexes.length && selectors.every(select => select.selectedIndex >= 0);
            const matches = valid ? variants.filter(item => Array.isArray(item.options) &&
              selectors.every((select, i) => item.options[indexes[i]] === select.value)) : [];
            if (matches.length === 1) variant = matches[0];
          } else if (root) {
            const matches = variants.filter(item => String(item.id) === variantInput?.value);
            if (matches.length === 1) variant = matches[0];
            else if (!variantInput?.value && variants.length === 1) variant = variants[0];
          }
          contextInvalid = !variant;
          if (contextError) contextError.hidden = !contextInvalid;
          form.querySelector('[type="submit"]').disabled = contextInvalid;
          field('Product_ID').value = source.dataset.quoteProductId;
          field('Requested_Product').value = source.dataset.quoteProductTitle;
          field('Variant_ID').value = variant ? String(variant.id) : '';
          field('Variant').value = variant?.title || decodeURIComponent((variant?.quote_title || '').replace(/\+/g, ' '));
          field('SKU').value = decodeURIComponent((variant?.quote_sku || '').replace(/\+/g, ' '));
          field('Quantity').value = quantityInput ? quantityInput.value : '1';
        } else if (document.querySelector('form input[name="product-id"]')) {
          contextInvalid = true;
          if (contextError) contextError.hidden = false;
          form.querySelector('[type="submit"]').disabled = true;
        }
      }
      preview();
    };
    const focusable = () => [...modal.querySelectorAll('button, input:not([type="hidden"]), textarea, select, a[href]')]
      .filter(element => !element.disabled && element.getClientRects().length);
    const open = (opener, result) => {
      if (modal.classList.contains('is-open')) return;
      returnFocus = opener || document.querySelector('[data-open-quote-modal]') || document.activeElement;
      previousOverflow = document.body.style.overflow;
      for (const element of document.body.children) {
        if (!element.contains(modal) && !element.inert) {
          element.inert = true;
          inertElements.push(element);
        }
      }
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
      (result || field('Name')).focus();
    };
    const close = () => {
      if (!modal.classList.contains('is-open')) return;
      modal.classList.remove('is-open');
      modal.setAttribute('aria-hidden', 'true');
      inertElements.forEach(element => { element.inert = false; });
      inertElements = [];
      document.body.style.overflow = previousOverflow;
      if (returnFocus?.isConnected) returnFocus.focus();
    };
    const cleanReturnMarker = () => {
      const url = new URL(location.href);
      if (!url.searchParams.has('quote_request')) return;
      url.searchParams.delete('quote_request');
      if (url.hash === '#QuoteForm') url.hash = '';
      history.replaceState(history.state, '', url);
    };

    document.addEventListener('click', event => {
      const opener = event.target.closest('[data-open-quote-modal]');
      if (opener) {
        event.preventDefault();
        clearResult();
        captureProduct(opener);
        open(opener);
      } else if (event.target.closest('[data-close-quote-modal]')?.closest('#QuoteModal') === modal) close();
    });
    document.addEventListener('keydown', event => {
      if (!modal.classList.contains('is-open')) return;
      if (event.key === 'Escape') { event.preventDefault(); close(); }
      if (event.key !== 'Tab') return;
      const controls = focusable();
      const first = controls[0], last = controls[controls.length - 1];
      if (event.shiftKey && (document.activeElement === first || !controls.includes(document.activeElement))) {
        event.preventDefault(); last?.focus();
      } else if (!event.shiftKey && (document.activeElement === last || !controls.includes(document.activeElement))) {
        event.preventDefault(); first?.focus();
      }
    });
    document.addEventListener('submit', event => {
      if (event.target !== form) {
        if (event.target.elements?.namedItem('form_type')?.value === 'contact') {
          clearPending();
          cleanReturnMarker();
        }
        return;
      }
      if (event.defaultPrevented) return;
      if (contextInvalid) { event.preventDefault(); contextError?.focus(); return; }
      if (!form.checkValidity()) { event.preventDefault(); form.reportValidity(); return; }
      const token = crypto.randomUUID();
      const url = new URL(location.href);
      url.searchParams.delete('contact_posted');
      url.searchParams.delete('form_type');
      url.searchParams.set('quote_request', token);
      url.hash = 'QuoteForm';
      form.elements.namedItem('return_to').value = url.pathname + url.search + url.hash;
      const action = new URL(form.action);
      action.searchParams.set('quote_request', token);
      action.hash = 'QuoteForm';
      form.action = action.href;
      const fields = {};
      for (const input of form.elements) {
        if (input.name?.startsWith('contact[')) fields[input.name] = input.value;
      }
      try { sessionStorage.setItem(storageKey, JSON.stringify({ token, time: Date.now(), fields })); } catch {}
    });

    const url = new URL(location.href);
    const token = url.searchParams.get('quote_request');
    const recent = pending && Date.now() - pending.time >= 0 && Date.now() - pending.time < 20 * 60 * 1000;
    const attributed = token && url.hash === '#QuoteForm' && (storageAvailable ? recent && pending.token === token : /^[a-f\d-]{36}$/i.test(token));
    const result = results.find(item => item.dataset.quoteResult === 'error') || results[0];
    if (attributed && result) {
      if (recent && pending.token === token) {
        for (const input of form.elements) {
          if (input.name?.startsWith('contact[') && Object.hasOwn(pending.fields || {}, input.name)) input.value = pending.fields[input.name];
        }
      }
      preview();
      result.hidden = false;
      if (result.dataset.quoteResult === 'error' && result.hasAttribute('data-quote-email-error')) {
        field('email').setAttribute('aria-invalid', 'true');
        field('email').setAttribute('aria-describedby', 'QuoteErrors');
      }
      open(null, result);
      clearPending();
    } else if (pending && !recent) clearPending();
    cleanReturnMarker();
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initialize, { once: true });
  else initialize();
})();

class CartDrawer {
    constructor() {
      this.drawer = document.getElementById('CartDrawer');
      this.overlay = document.getElementById('CartDrawerOverlay');
      this.closeBtn = document.getElementById('CartDrawerClose');
      this.continueBtn = document.getElementById('CartDrawerContinue');

      this.pending = false;
      this.unsynced = false;
      this.init();
    }

    init() {
      if (this.closeBtn) this.closeBtn.addEventListener('click', () => this.close());
      if (this.overlay) this.overlay.addEventListener('click', () => this.close());


      this.bindEvents();
    }

    focusableElements() {
      return [...this.drawer.querySelectorAll('a[href], button, input, select, textarea, summary, [tabindex], [contenteditable="true"]')]
        .filter(element => element.tabIndex >= 0 && !element.matches(':disabled') && !element.closest('[inert], [hidden]') && element.getClientRects().length && getComputedStyle(element).visibility !== 'hidden');
    }

    focusInside(preferred) {
      const elements = this.focusableElements();
      (elements.includes(preferred) ? preferred : elements.includes(this.closeBtn) ? this.closeBtn : elements[0] || this.drawer).focus({ preventScroll: true });
    }

    open(trigger = this.pendingTrigger || document.activeElement) {
      if (document.querySelector('#QuoteModal.is-open')) return;
      if (this.drawer && this.overlay) {
        if (this.drawer.classList.contains('is-open')) return;
        this.returnFocus = trigger && !this.drawer.contains(trigger) ? trigger : null;
        this.previousOverflow = document.body.style.overflow;
        this.previousTabIndex = this.drawer.getAttribute('tabindex');
        this.drawer.setAttribute('tabindex', '-1');
        this.drawer.classList.add('is-open');
        this.drawer.setAttribute('aria-hidden', 'false');
        this.drawer.removeAttribute('inert');
        this.overlay.classList.add('is-active');
        document.body.style.overflow = 'hidden';
        this.focusListeners = new AbortController();
        const options = { capture: true, signal: this.focusListeners.signal };
        document.addEventListener('keydown', event => {
          if (event.key === 'Escape') {
            event.preventDefault();
            event.stopPropagation();
            this.close();
          } else if (event.key === 'Tab') {
            const elements = this.focusableElements();
            const index = elements.indexOf(document.activeElement);
            if (!elements.length || index === -1 || (event.shiftKey ? index === 0 : index === elements.length - 1)) {
              event.preventDefault();
              this.focusInside(event.shiftKey ? elements[elements.length - 1] : elements[0]);
            }
          }
        }, options);
        document.addEventListener('focusin', event => {
          if (document.querySelector('#QuoteModal.is-open')) this.close(false);
          else if (!this.drawer.contains(event.target)) this.focusInside();
        }, options);
        this.focusInside();
      }
    }

    close(restoreFocus = true) {
      if (this.drawer && this.overlay && this.drawer.classList.contains('is-open')) {
        this.focusListeners?.abort();
        this.focusListeners = null;
        this.drawer.classList.remove('is-open');
        this.overlay.classList.remove('is-active');
        if (!document.querySelector('#QuoteModal.is-open')) {
          document.body.style.overflow = this.previousOverflow;
          if (restoreFocus) {
            const usable = element => element?.isConnected && !element.matches(':disabled') && !element.closest('[inert], [hidden]') && element.getClientRects().length && getComputedStyle(element).visibility !== 'hidden';
            const fallback = [...document.querySelectorAll('a[href]')].find(element => !this.drawer.contains(element) && usable(element) && new URL(element.href).pathname === window.Shopify.routes.root + 'cart');
            const target = usable(this.returnFocus) ? this.returnFocus : fallback;
            if (target) target.focus({ preventScroll: true });
            else {
              const main = document.querySelector('main, #MainContent') || document.body;
              const tabIndex = main.getAttribute('tabindex');
              main.setAttribute('tabindex', '-1');
              main.focus({ preventScroll: true });
              if (tabIndex === null) main.removeAttribute('tabindex'); else main.setAttribute('tabindex', tabIndex);
            }
          }
        }
        this.returnFocus = null;
        this.drawer.setAttribute('aria-hidden', 'true');
        this.drawer.setAttribute('inert', '');
        if (this.previousTabIndex === null) this.drawer.removeAttribute('tabindex');
        else this.drawer.setAttribute('tabindex', this.previousTabIndex);
      }
    }

    bindEvents() {
      document.addEventListener('click', (e) => {
        if ((this.pending || this.unsynced) && e.target.closest('a[href$="/checkout"]')) { e.preventDefault(); return; }
        if (e.target.closest('#CartDrawerContinue')) this.close();
        if (e.target.closest('#CartFeedbackRetry')) this.run(() => this.refreshDrawer(), true);
        // Modificar cantidad (+ / -)
        if (e.target.classList.contains('js-qty-btn')) {
          const key = e.target.getAttribute('data-key');
          const action = e.target.getAttribute('data-action');
          const input = e.target.parentElement.querySelector('.js-qty-input');
          let currentQty = parseInt(input.value) || 0;

          if (action === 'plus') currentQty += 1;
          if (action === 'minus') currentQty -= 1;

          this.updateQuantity(key, currentQty);
        }

        // Eliminar producto
        if (e.target.classList.contains('js-remove-item')) {
          const key = e.target.getAttribute('data-key');
          this.updateQuantity(key, 0);
        }
      });
      document.addEventListener('change', e => {
        if (e.target.matches('.js-qty-input')) this.updateQuantity(e.target.dataset.key, e.target.value === '' ? NaN : Number(e.target.value));
      });
      document.addEventListener('submit', e => {
        const url = new URL(e.target.action, window.location.href);
        if ((this.pending || this.unsynced) && url.origin === window.location.origin && [window.Shopify.routes.root + 'cart/add', window.Shopify.routes.root + 'cart'].includes(url.pathname)) e.preventDefault();
      });
    }

    feedback(message) {
      const region = document.getElementById('CartFeedback');
      if (region) { region.textContent = message; region.hidden = !message; }
      const retry = document.getElementById('CartFeedbackRetry');
      if (retry) retry.hidden = !this.unsynced;
    }

    errorMessage(kind = 'error') {
      return document.getElementById('CartFeedback')?.dataset[kind] || 'Unable to update cart.';
    }

    async request(url, options = {}) {
      const response = await fetch(url, { signal: AbortSignal.timeout(15000), ...options, headers: { Accept: 'application/json', ...options.headers } });
      let data;
      try { data = await response.json(); } catch { throw new Error(this.errorMessage()); }
      if (!response.ok) {
        const errors = data?.errors && typeof data.errors === 'object' ? Object.values(data.errors).flat().filter(value => typeof value === 'string').join(' ') : data?.errors;
        const message = [data?.description, data?.message, errors].find(value => typeof value === 'string' && value.trim());
        throw Object.assign(new Error(message || this.errorMessage()), { status: response.status });
      }
      if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error(this.errorMessage());
      return data;
    }

    async run(work, recovery = false) {
      if (this.pending || (this.unsynced && !recovery)) return false;
      this.pending = true;
      this.pendingTrigger = document.activeElement;
      const page = document.getElementById('main-cart-container');
      const row = this.pendingTrigger?.closest('[data-line-item-key]');
      if (page?.contains(row)) {
        this.pageFocusRequest = {
          trigger: this.pendingTrigger, key: row.dataset.lineItemKey,
          tagName: this.pendingTrigger.tagName, action: this.pendingTrigger.dataset.action,
          remove: this.pendingTrigger.classList.contains('js-remove-cart-item'), cancelled: false
        };
      } else if (!recovery || this.pendingTrigger?.id !== 'CartFeedbackRetry') this.pageFocusRequest = null;
      const intent = this.pageFocusRequest;
      const trackFocus = event => {
        if (intent && event.target !== intent.trigger && event.target !== document.body && event.target.id !== 'CartFeedbackRetry') intent.cancelled = true;
      };
      document.addEventListener('focusin', trackFocus);
      this.feedback('');
      const controls = [...document.querySelectorAll('.js-add-to-cart-btn, .js-qty-btn, .js-remove-item, .js-qty-input, .js-qty-change, .js-remove-cart-item, #CartFeedbackRetry, button[name="checkout"]')].filter(control => !control.disabled);
      controls.forEach(control => { control.disabled = true; });
      try { await work(); this.feedback(''); return true; }
      catch (error) {
        this.unsynced = true;
        if (!recovery) { try { await this.refreshDrawer(); } catch {} }
        this.feedback(this.unsynced ? this.errorMessage('refreshError') : error.message || this.errorMessage());
        return false;
      } finally {
        document.removeEventListener('focusin', trackFocus);
        if (!this.unsynced) this.pageFocusRequest = null;
        controls.forEach(control => { if (control.isConnected) control.disabled = false; });
        document.querySelectorAll('#main-cart-form button[name="checkout"]').forEach(control => { control.disabled = this.unsynced; });
        if (this.unsynced && intent && !intent.cancelled && document.activeElement === document.body &&
            intent.trigger.isConnected && !intent.trigger.disabled && !this.drawer.classList.contains('is-open')) intent.trigger.focus({ preventScroll: true });
        this.pending = false;
        this.pendingTrigger = null;
      }
    }

    updateQuantity(key, quantity) {
      if (!Number.isSafeInteger(quantity) || quantity < 0) { this.feedback(this.errorMessage()); return Promise.resolve(false); }
      return this.run(async () => {
        const cart = await this.request(window.Shopify.routes.root + 'cart/change.js', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id: key, quantity })
        });
        if (!Array.isArray(cart.items)) throw new Error(this.errorMessage());
        await this.refreshDrawer();
      });
    }

    async refreshDrawer() {
      const url = new URL(window.location.href);
      const page = document.getElementById('main-cart-container');
      const pageSection = page?.dataset.cartSectionId;
      if (page && !pageSection) throw new Error(this.errorMessage('refreshError'));
      url.searchParams.set('sections', pageSection ? 'cart-drawer,' + pageSection : 'cart-drawer');
      // Request section rendering, rather than the cart/product JSON representation.
      const sections = await this.request(url.toString(), { headers: { Accept: 'text/html' } });
      if (typeof sections['cart-drawer'] !== 'string') throw new Error(this.errorMessage('refreshError'));
      const html = new DOMParser().parseFromString(sections['cart-drawer'], 'text/html');
      const newBody = html.getElementById('CartDrawerBody');
      const newCount = html.getElementById('CartDrawerCount');
      const newFooter = html.getElementById('CartDrawerFooter');
      const body = document.getElementById('CartDrawerBody');
      const count = document.getElementById('CartDrawerCount');
      const footer = document.getElementById('CartDrawerFooter');
      if (!newBody || !newCount || !body || !count || !this.drawer) throw new Error(this.errorMessage('refreshError'));
      let newPage;
      const active = document.activeElement;
      const currentPageFocus = page?.contains(active) ? active : null;
      const savedFocus = this.pageFocusRequest;
      const restoreSaved = savedFocus && !savedFocus.cancelled && !this.drawer.classList.contains('is-open') &&
        (active === document.body || active === savedFocus.trigger || active?.id === 'CartFeedbackRetry');
      const pageFocus = currentPageFocus ? {
        key: currentPageFocus.closest('[data-line-item-key]')?.dataset.lineItemKey,
        tagName: currentPageFocus.tagName, action: currentPageFocus.dataset.action,
        remove: currentPageFocus.classList.contains('js-remove-cart-item')
      } : restoreSaved ? savedFocus : null;
      if (page) {
        if (typeof sections[pageSection] !== 'string') throw new Error(this.errorMessage('refreshError'));
        const pageHTML = new DOMParser().parseFromString(sections[pageSection], 'text/html');
        newPage = pageHTML.getElementById('main-cart-container');
        const countValue = Number(newCount.textContent.replace(/[()]/g, '').trim());
        if (!newPage || newPage.dataset.cartSectionId !== pageSection || !Number.isSafeInteger(countValue) || countValue < 0 ||
            (countValue === 0 ? !newPage.querySelector('[data-cart-empty]') || newPage.querySelector('#main-cart-form') :
              !newPage.querySelector('#main-cart-form') || !newPage.querySelector('#cart-subtotal'))) throw new Error(this.errorMessage('refreshError'));
        const pageLines = [...newPage.querySelectorAll('[data-line-item-key]')];
        const drawerLines = [...newBody.querySelectorAll('.cart-drawer-item')];
        const keys = pageLines.map(row => row.dataset.lineItemKey);
        const quantities = pageLines.map(row => Number(row.querySelector('input[type="number"]')?.value));
        if (new Set(keys).size !== keys.length || keys.some(key => !key) || quantities.some(value => !Number.isSafeInteger(value) || value < 1) ||
            quantities.reduce((total, value) => total + value, 0) !== countValue || pageLines.length !== drawerLines.length || pageLines.some(row => {
          const input = row.querySelector('input[type="number"]');
          const line = drawerLines.find(item => item.dataset.key === row.dataset.lineItemKey);
          return !input || !line || input.value !== line.querySelector('.js-qty-input')?.value;
        })) throw new Error(this.errorMessage('refreshError'));
      }
      const focused = this.drawer.contains(document.activeElement) ? document.activeElement : null;
      body.innerHTML = newBody.innerHTML;
      count.textContent = newCount.textContent;
      if (footer) { if (newFooter) footer.replaceWith(newFooter); else footer.remove(); }
      else if (newFooter) body.after(newFooter);
      document.querySelectorAll('.site-header__cart-count').forEach(badge => { badge.textContent = newCount.textContent.replace(/[()]/g, '').trim(); });
      if (this.drawer.classList.contains('is-open') && (!this.drawer.contains(document.activeElement) || document.activeElement.matches(':disabled'))) {
        const replacement = focused && this.focusableElements().find(element =>
          (focused.id && element.id === focused.id) ||
          (focused.dataset.key && element.dataset.key === focused.dataset.key && element.tagName === focused.tagName && element.dataset.action === focused.dataset.action) ||
          (focused.tagName === 'A' && element.tagName === 'A' && element.getAttribute('href') === focused.getAttribute('href')));
        this.focusInside(replacement);
      }
      if (page) {
        page.innerHTML = newPage.innerHTML;
        if (pageFocus) {
          const row = [...page.querySelectorAll('[data-line-item-key]')].find(item => item.dataset.lineItemKey === pageFocus.key);
          const replacement = row && [...row.querySelectorAll('button, input, a')].find(item =>
            !item.disabled && item.tagName === pageFocus.tagName && item.dataset.action === pageFocus.action &&
            (pageFocus.tagName !== 'BUTTON' || item.classList.contains('js-remove-cart-item') === pageFocus.remove));
          if (replacement) replacement.focus({ preventScroll: true });
          else {
            page.setAttribute('tabindex', '-1');
            page.focus({ preventScroll: true });
          }
        }
      }
      this.unsynced = false;
      document.dispatchEvent(new CustomEvent('cart:reconciled'));
    }

  }

  // Inicializar globalmente para poder invocarlo desde los botones de Add to Cart
  window.cartDrawer = new CartDrawer();

  document.addEventListener('DOMContentLoaded', () => {
    // Solo intercepta clics en /cart si vienen de enlaces fuera de la página de carrito activa
    const isCartPage = window.location.pathname.includes('/cart');

    if (!isCartPage) {
      const cartLinks = document.querySelectorAll('a[href="/cart"], a[href*="/cart"]');
      cartLinks.forEach(link => {
        if (!link.closest('#CartDrawer')) {
          link.addEventListener('click', (e) => {
            e.preventDefault();
            if (window.cartDrawer) window.cartDrawer.open();
          });
        }
      });
    }
  });

