/* ==========================================================================
   1. MAIN PRODUCT LAYOUT & CONTAINERS (DESKTOP >= 768px)
   ========================================================================== */
   .product-page {
    padding-top: 24px;
    padding-bottom: 40px;
  }

  .product-page__back {
    margin-bottom: 20px;
    width: 100%;
  }

  .product-page__back .back-link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #1d1d1f;
    text-decoration: none;
    font-size: 0.85rem;
    font-weight: 500;
  }

  .product-master-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    align-items: start;
  }

  .product-left-col {
    display: flex !important;
    flex-direction: column !important;
    gap: 18px;
  }

  .product-right-col {
    display: flex;
    flex-direction: column;
    gap: 20px;
  }

  /* ==========================================================================
     2. PRODUCT TYPOGRAPHY & HEADINGS
     ========================================================================== */
  .product-info__title {
    font-size: 2.2rem;
    font-weight: 700;
    color: #ab273b;
    margin: 0;
    line-height: 1.15;
    letter-spacing: -0.015em;
  }

  .product-info__subtitle {
    font-size: 1.5rem;
    font-weight: 700;
    color: #ab273b;
    margin: 12px 0 0 0;
    line-height: 1.25;
  }

  .product-info__intro-highlight {
    border-left: 3px solid #ab273b;
    padding-left: 16px;
    margin: 4px 0;
  }

  .product-info__intro-highlight p,
  .product-info__intro-highlight strong {
    font-weight: 700;
    color: #333333;
    font-size: 0.92rem;
    line-height: 1.5;
    margin: 0;
  }

  .product-info__description {
    font-size: 0.9rem;
    color: #515154;
    line-height: 1.6;
  }

  /* ==========================================================================
     3. BUY BOX, OPTIONS & CONTROLS
     ========================================================================== */
  .product-buy-box {
    display: flex;
    flex-direction: column;
    gap: 14px;
    margin-top: 16px;
  }

  .product-price {
    font-size: 1.25rem;
    font-weight: 500;
    color: #1d1d1f;
  }

  .product-buy-row {
    display: flex;
    gap: 12px;
    align-items: center;
    max-width: 420px;
  }

  .product-quantity {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    border: 1px solid #d2d2d7;
    border-radius: 4px;
    background: #ffffff;
    height: 44px;
  }

  .product-quantity button {
    min-width: 44px;
    min-height: 44px;
    background: none;
    border: none;
    padding: 0 14px;
    font-size: 1rem;
    cursor: pointer;
    color: #515154;
    height: 44px;
  }

  .product-quantity input {
    width: 40px;
    border: none;
    text-align: center;
    font-size: 0.9rem;
    font-weight: 500;
    color: #1d1d1f;
  }

  .product-add-cart-btn {
    flex: 1;
    height: 44px;
    background-color: #ab273b;
    color: #ffffff;
    border: none;
    padding: 0 20px;
    border-radius: 6px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    cursor: pointer;
    transition: background-color 0.2s ease;
  }

  .product-add-cart-btn:hover {
    background-color: #8c1e2e;
  }

  .product-options-container {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 12px;
  }

  .product-option {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .product-option label {
    font-size: 0.85rem;
    font-weight: 600;
    color: #1d1d1f;
  }

  .product-select {
    width: 100%;
    height: 44px;
    min-height: 44px;
    padding: 0 14px;
    border-radius: 6px;
    border: 1px solid #d2d2d7;
    background-color: #ffffff;
    font-size: 0.88rem;
    color: #1d1d1f;
    outline: none;
    cursor: pointer;
  }

  /* ==========================================================================
     4. GALLERY & MEDIA COMPONENTS
     ========================================================================== */
  .product-gallery {
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }

  .product-gallery__main {
    flex: 1;
    border-radius: 24px;
    overflow: hidden;
    background-color: #f5f5f7;
    min-height: 480px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .product-gallery__main img {
    width: 100%;
    height: 100%;
    min-height: 480px;
    object-fit: contain;
    border-radius: 24px;
    display: block;
  }

  .product-gallery__thumbs {
    display: flex;
    flex-direction: column;
    gap: 12px;
    width: 76px;
  }

  .thumb-img, 
  .thumb-img-placeholder {
    width: 76px;
    height: 76px;
    border-radius: 12px;
    background-color: #f5f5f7;
    object-fit: cover;
    cursor: pointer;
    border: 1px solid #d2d2d7;
    transition: all 0.2s ease;
  }

  .thumb-img.is-active {
    border-color: #ab273b;
    box-shadow: 0 0 0 2px #ab273b;
  }

  .product-compare-wrapper {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-top: 12px;
    padding-right: 92px;
    width: 100%;
  }

  .product-compare-trigger-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background-color: #ffffff;
    color: #ab273b;
    border: 1px solid #ab273b;
    padding: 8px 18px;
    border-radius: 980px;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
  }

  /* ==========================================================================
     5. COLOR SWATCHES & SELECTORS
     ========================================================================== */
  .product-swatches-below-gallery {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 16px;
    margin-bottom: 12px;
    align-items: center;
  }

  .product-swatch-btn {
    width: 40px !important;
    height: 40px !important;
    border-radius: 50% !important;
    border: 2px solid #d2d2d7 !important;
    padding: 0 !important;
    cursor: pointer !important;
    position: relative !important;
    display: inline-block !important;
    font-size: 0 !important;
    color: transparent !important;
    text-indent: -9999px !important;
    overflow: hidden !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.08);
    transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  }

  .product-swatch-btn * {
    display: none !important;
  }

  .product-swatch-btn:hover {
    transform: scale(1.1);
    border-color: #1d1d1f !important;
  }

  .product-swatch-btn.is-active {
    border-color: #ab273b !important;
    transform: scale(1.12);
    box-shadow: 0 0 0 3px rgba(171, 39, 59, 0.2);
  }

  /* ==========================================================================
     6. ACCORDIONS, SHIPPING & TECHNICAL TABLES
     ========================================================================== */
  .product-characteristics-grid {
    margin-top: 40px;
    align-items: stretch;
  }

  .product-characteristics-left {
    display: flex;
    flex-direction: column;
    height: 100%;
  }

  .product-acc-title {
    font-size: 1.25rem;
    font-weight: 700;
    color: #1d1d1f;
    margin: 0 0 16px 0;
  }

  .product-acc-list {
    display: flex;
    flex-direction: column;
    border-top: 1px solid #e5e5e7;
    margin-bottom: 24px;
  }

  .product-acc-item {
    border-bottom: 1px solid #e5e5e7;
    padding: 14px 0;
  }

  .product-acc-item summary {
    font-weight: 600;
    font-size: 0.95rem;
    color: #1d1d1f;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    list-style: none;
  }

  .product-acc-item summary::-webkit-details-marker {
    display: none;
  }

  .product-acc-content {
    padding-top: 10px;
    color: #515154;
    font-size: 0.88rem;
    line-height: 1.5;
  }

  .product-shipping-block {
    margin-top: auto;
    background: #f5f5f7;
    border-radius: 12px;
    padding: 20px;
    border: 1px solid #e5e5e7;
  }

  .product-shipping__title {
    font-size: 0.98rem;
    font-weight: 700;
    color: #1d1d1f;
    margin: 0 0 6px 0;
  }

  .shipping-description {
    font-size: 0.86rem;
    color: #515154;
    line-height: 1.45;
  }

  .shipping-description p {
    margin: 0;
  }

  .equipro-specs-container,
  .tech-table-container {
    width: 100%;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid #e5e5e7;
    background: #ffffff;
  }

  .equipro-table,
  .tech-table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
  }

  .equipro-table th,
  .tech-table th {
    background-color: #ab273b;
    color: #ffffff;
    font-size: 0.78rem;
    font-weight: 700;
    padding: 12px 16px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border: none;
  }

  .equipro-table td,
  .tech-table td {
    padding: 12px 16px;
    font-size: 0.82rem;
    color: #1d1d1f;
    border-bottom: 1px solid #e5e5e7;
    line-height: 1.45;
  }

  .equipro-table tr:last-child td,
  .tech-table tr:last-child td {
    border-bottom: none;
  }

  .equipro-table td.feature-label,
  .tech-table__label {
    font-weight: 700;
    color: #ab273b;
    width: 38%;
  }

  /* ==========================================================================
     7. MOBILE RESPONSIVE LAYOUT ( <= 767px )
     ========================================================================== */
  @media screen and (max-width: 767px) {
    .product-master-grid {
      display: flex;
      flex-direction: column;
      gap: 1.25rem;
    }

    .product-left-col,
    .product-right-col {
      display: contents !important;
    }

    .product-gallery {
      flex-direction: column;
      width: 100%;
    }

    .product-gallery__thumbs {
      flex-direction: row;
      justify-content: center;
      width: 100%;
    }

    .product-gallery__thumbs .thumb-img,
    .product-gallery__thumbs .thumb-img-placeholder {
      width: 76px;
      height: 76px;
    }

    .product-mobile-order-gallery { 
      order: 1; 
      width: 100%; 
    }

    .product-mobile-order-title { 
      order: 2; 
      width: 100%; 
      margin-top: 0.5rem; 
      margin-bottom: 0.25rem; 
    }

    .product-mobile-order-buybox { 
      order: 3; 
      width: 100%; 
    }

    .product-mobile-order-descriptions { 
      order: 4; 
      width: 100%; 
      margin-top: 0.5rem; 
    }

    .product-mobile-order-compare { 
      order: 5; 
      width: 100%; 
      margin-top: 1.5rem; 
      padding-right: 0; 
    }

    .product-shipping-block {
      margin-top: 24px;
    }
  }

/* Product-form feedback and native variant fallback stay inside the buy box. */
.product-page equipro-product-form { display: block; }
.product-page [data-js-product-controls][hidden],
.product-page .product-form-feedback [hidden] { display: none !important; }
.product-page .product-form-feedback { font-size: .875rem; line-height: 1.5; overflow-wrap: anywhere; }
.product-page equipro-product-form.has-feedback .product-form-feedback { margin-top: 12px; }
.product-page .product-form-status, .product-page .product-form-error { margin: 0; }
.product-page .product-form-error { color: #92283b; }
.product-page .product-form-actions { display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center; margin-top: 8px; }
.product-page .product-form-actions a, .product-page .product-form-actions button,
.product-page .product-native-variants a { display: inline-flex; align-items: center; min-height: 44px; color: #92283b; }
.product-page .product-form-actions button { padding: 8px 12px; border: 1px solid currentColor; border-radius: 6px; background: transparent; font: inherit; cursor: pointer; }
.product-page .product-form-actions button:disabled { opacity: .6; cursor: wait; }
.product-page .product-form-actions :focus-visible, .product-page .product-native-variants a:focus-visible,
.product-page .product-add-cart-btn:focus-visible, .product-page .product-select:focus-visible { outline: 2px solid #92283b; outline-offset: 3px; }
.product-page .product-native-variants ul { display: flex; flex-wrap: wrap; gap: 4px 16px; list-style: none; padding: 0; }
.product-page .product-native-variants [aria-current="page"] { font-weight: 700; }

/* Keep native number controls when the scripted quantity buttons are hidden. */
.product-page .product-quantity > [data-js-product-controls]:not([hidden]) + input[type="number"] { appearance: textfield; -moz-appearance: textfield; }
.product-page .product-quantity > [data-js-product-controls]:not([hidden]) + input[type="number"]::-webkit-inner-spin-button,
.product-page .product-quantity > [data-js-product-controls]:not([hidden]) + input[type="number"]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
.product-page .product-quantity input:focus-visible { outline: 2px solid #92283b; outline-offset: 2px; }

/* Four-image gallery controls retain the existing thumbnail composition. */
.product-gallery__thumbs button.thumb-img { padding: 0; overflow: hidden; }
.product-gallery__thumbs button.thumb-img img { display: block; width: 100%; height: 100%; object-fit: cover; border-radius: inherit; }
.product-gallery__thumbs button.thumb-img:focus-visible { outline: 2px solid #92283b; outline-offset: 3px; }

{{ 'section-main-product.css' | asset_url | stylesheet_tag }}
<script src="{{ 'product-form.js' | asset_url }}" defer="defer"></script>

<div class="product-page page-width" id="ProductMain-{{ section.id }}">
  {% assign target_product = product | default: section.settings.featured_product %}
  {% assign use_product_overrides = true %}
  {% if product != blank and section.settings.featured_product != blank and section.settings.featured_product.id != product.id %}
    {% assign use_product_overrides = false %}
  {% endif %}

  {% liquid
    assign purchase_restricted = false
    assign template_name = target_product.template_suffix | downcase
    if template_name contains 'quote' or target_product.requires_selling_plan
      assign purchase_restricted = true
    endif
    for tag in target_product.tags
      assign normalized_tag = tag | downcase
      if normalized_tag contains 'quote' or normalized_tag == 'rfq'
        assign purchase_restricted = true
      endif
    endfor
    for product_collection in target_product.collections
      if product_collection.handle == 'portable' or product_collection.handle == 'portable-tables'
        assign purchase_restricted = true
      endif
    endfor
  %}

  <!-- 1. BACK LINK -->
  <div class="product-page__back product-mobile-order-back">
    <a href="javascript:history.back()" class="back-link">
      <svg width="8" height="12" viewBox="0 0 8 12" fill="none">
        <path d="M7 1L1 6L7 11" stroke="#1d1d1f" stroke-width="1.5" stroke-linecap="round"/>
      </svg>
      <span>{{ section.settings.back_text | default: "Back" }}</span>
    </a>
  </div>

  <!-- PART 1: MAIN GRID (TOP) -->
  <div class="product-master-grid">

    <!-- LEFT COLUMN -->
    <div class="product-left-col">

      <!-- PRODUCT TITLE -->
      <h1 class="product-info__title product-mobile-order-title">
        {% if use_product_overrides %}{{ section.settings.custom_title | default: target_product.title | escape }}{% else %}{{ target_product.title | escape }}{% endif %}
      </h1>

      <!-- DESCRIPTIONS AND HIGHLIGHTS -->
      <div class="product-mobile-order-descriptions">
        {% assign intro_text = section.settings.intro_highlight %}
        {% if use_product_overrides and intro_text != blank %}
          <div class="product-info__intro-highlight">
            <p>{{ intro_text }}</p>
          </div>
        {% endif %}

        <div class="product-info__description">
          {% if use_product_overrides and section.settings.custom_description != blank %}
            {{ section.settings.custom_description }}
          {% else %}
            {{ target_product.description }}
          {% endif %}
        </div>

        {% if use_product_overrides and section.settings.subtitle != blank %}
          <h2 class="product-info__subtitle">{{ section.settings.subtitle }}</h2>
        {% endif %}

        {% if use_product_overrides and section.settings.secondary_description != blank %}
          <div class="product-info__description">
            {{ section.settings.secondary_description }}
          </div>
        {% endif %}
      </div>

      <!-- BUY BOX -->
      <div class="product-buy-box product-mobile-order-buybox">
        <!-- DYNAMIC PRICE -->
        <div class="product-price" id="ProductPriceContainer">
          {% assign current_variant = target_product.selected_or_first_available_variant %}
          {% if current_variant.price > 0 %}{{ current_variant.price | money }}{% else %}{{ 'products.price_unavailable' | t }}{% endif %}
        </div>

        <equipro-product-form
          data-ajax-eligible="{% if purchase_restricted == false and target_product.gift_card? != true %}true{% else %}false{% endif %}"
          data-product-label="{{ target_product.title | escape }}"
          data-add-label="{{ section.settings.btn_label | default: 'ADD TO CART' | escape }}"
          data-adding="{{ 'products.form.adding' | t | escape }}"
          data-added="{{ 'products.form.added' | t: variant: '__VARIANT__' | escape }}"
          data-accepted="{{ 'products.form.accepted' | t | escape }}"
          data-uncertain="{{ 'products.form.uncertain' | t | escape }}"
          data-invalid="{{ 'products.form.invalid' | t | escape }}"
          data-unavailable="{{ 'products.purchase_unavailable' | t | escape }}"
          data-soldout="{{ 'products.form.sold_out' | t | escape }}"
          data-request-error="{{ 'cart.request_error' | t | escape }}"
        >
        {% form 'product', target_product %}
          <input type="hidden" name="id" id="ProductVariantIdInput" value="{% if current_variant.available and current_variant.price > 0 and purchase_restricted == false and current_variant.requires_selling_plan != true %}{{ current_variant.id }}{% endif %}">

          {% if section.settings.show_variant_selectors and target_product.has_only_default_variant == false %}
            <div class="product-options-container" data-js-product-controls hidden>
              {% for option in target_product.options_with_values %}
                {% assign option_name_downcase = option.name | downcase %}

                {% assign show_option = true %}
                {% if option_name_downcase contains 'color' or option_name_downcase contains 'couleur' %}
                  {% if section.settings.show_color_option == false %}
                    {% assign show_option = false %}
                  {% endif %}
                {% elsif option_name_downcase contains 'size' or option_name_downcase contains 'talla' %}
                  {% if section.settings.show_size_option == false %}
                    {% assign show_option = false %}
                  {% endif %}
                {% endif %}

                {% if show_option %}
                  <div class="product-option">
                    <label for="Option-{{ section.id }}-{{ forloop.index0 }}">{% assign display_option_name = option.name | strip | downcase %}{% if display_option_name == 'couleur' or display_option_name == 'color' or display_option_name == 'colour' %}{{ 'products.color' | t }}{% else %}{{ option.name }}{% endif %}</label>
                    <select 
                      id="Option-{{ section.id }}-{{ forloop.index0 }}" 
                      class="product-select product-variant-selector"
                      data-option-index="{{ forloop.index0 }}"
                    >
                      {% for value in option.values %}
                        <option value="{{ value | escape }}" {% if option.selected_value == value %}selected="selected"{% endif %}>
                          {{ value }}
                        </option>
                      {% endfor %}
                    </select>
                  </div>
                {% endif %}
              {% endfor %}
            </div>
          {% endif %}

          <noscript>
            {% if target_product.variants.size > 1 %}
              <nav class="product-native-variants" aria-label="{{ 'products.form.choose_variant' | t | escape }}">
                <p>{{ 'products.form.choose_variant' | t }}</p>
                <ul>
                  {% for variant in target_product.variants %}
                    <li><a href="{{ target_product.url }}?variant={{ variant.id }}"{% if variant.id == current_variant.id %} aria-current="page"{% endif %}>{{ variant.title | escape }}</a></li>
                  {% endfor %}
                </ul>
              </nav>
            {% endif %}
          </noscript>

          <div class="product-buy-row">
            <div class="product-quantity">
              <button type="button" data-js-product-controls hidden aria-label="{{ 'cart.decrease_quantity' | t: product: target_product.title | escape }}" onclick="adjustQty(-1)">−</button>
              <input type="number" id="QuantityInput" name="quantity" value="1" min="1" aria-label="{{ 'cart.quantity_label' | t: product: target_product.title | escape }}">
              <button type="button" data-js-product-controls hidden aria-label="{{ 'cart.increase_quantity' | t: product: target_product.title | escape }}" onclick="adjustQty(1)">+</button>
            </div>

            <button type="submit" class="product-add-cart-btn" id="AddToCartButton" {% if current_variant.available == false or current_variant.price <= 0 or purchase_restricted or current_variant.requires_selling_plan %}disabled{% endif %}>
              {% if current_variant.price <= 0 or purchase_restricted or current_variant.requires_selling_plan %}
                {{ 'products.purchase_unavailable' | t }}
              {% elsif current_variant.available %}
                {{ section.settings.btn_label | default: "ADD TO CART" }}
              {% else %}
                OUT OF STOCK
              {% endif %}
            </button>
          </div>
          <div class="product-form-feedback">
            <p class="product-form-status" data-product-status role="status" aria-live="polite" aria-atomic="true"></p>
            <p class="product-form-error" data-product-error role="alert" hidden></p>
            <div class="product-form-actions" data-product-actions hidden>
              <a href="{{ routes.cart_url }}">{{ 'products.form.view_cart' | t }}</a>
              <button type="button" data-product-retry hidden>{{ 'cart.refresh' | t }}</button>
              <button type="button" data-product-checked hidden>{{ 'products.form.checked' | t }}</button>
            </div>
          </div>
        {% endform %}
        </equipro-product-form>
      </div>

    </div>

    <!-- RIGHT COLUMN (GALLERY AND COLOR SWATCHES) -->
    <div class="product-right-col product-mobile-order-gallery">
      <div class="product-gallery" data-product-gallery>

        <!-- MAIN IMAGE -->
        <div class="product-gallery__main">
          {% assign first_img_block = section.blocks | where: "type", "gallery_image" | first %}
          {% if use_product_overrides and first_img_block.settings.image != blank %}
            <img width="{{ first_img_block.settings.image.width }}" height="{{ first_img_block.settings.image.height }}" id="MainProductImg" src="{{ first_img_block.settings.image | image_url: width: 1600 }}" alt="{{ first_img_block.settings.image.alt | escape }}">
          {% elsif current_variant.image != blank %}
            <img width="{{ current_variant.image.width }}" height="{{ current_variant.image.height }}" id="MainProductImg" src="{{ current_variant.image | image_url: width: 1600 }}" alt="{{ current_variant.image.alt | default: target_product.title | escape }}">
          {% elsif target_product.featured_image != blank %}
            <img width="{{ target_product.featured_image.width }}" height="{{ target_product.featured_image.height }}" id="MainProductImg" src="{{ target_product.featured_image | image_url: width: 1600 }}" alt="{{ target_product.featured_image.alt | default: target_product.title | escape }}">
          {% else %}
            <div class="thumb-img-placeholder"></div>
          {% endif %}
        </div>

        <!-- THUMBNAILS -->
        <div class="product-gallery__thumbs">
          {% assign img_blocks = section.blocks | where: "type", "gallery_image" %}
          {% if use_product_overrides and img_blocks.size > 0 %}
            {% for block in img_blocks limit: 4 %}
              {% if block.settings.image != blank %}
                <button type="button" class="thumb-img" aria-pressed="false"
                  aria-label="{{ 'products.gallery.show_image' | t: number: forloop.index, product: target_product.title | escape }}"
                  data-gallery-src="{{ block.settings.image | image_url: width: 1600 }}"
                  data-gallery-alt="{{ block.settings.image.alt | default: target_product.title | escape }}"
                  data-gallery-width="{{ block.settings.image.width }}" data-gallery-height="{{ block.settings.image.height }}" {{ block.shopify_attributes }}>
                  <img width="{{ block.settings.image.width }}" height="{{ block.settings.image.height }}"
                    src="{{ block.settings.image | image_url: width: 400 }}" alt="">
                </button>
              {% endif %}
            {% endfor %}
          {% elsif target_product.images.size > 0 %}
            {% for image in target_product.images limit: 4 %}
              <button type="button" class="thumb-img" aria-pressed="false"
                aria-label="{{ 'products.gallery.show_image' | t: number: forloop.index, product: target_product.title | escape }}"
                data-gallery-src="{{ image | image_url: width: 1600 }}"
                data-gallery-alt="{{ image.alt | default: target_product.title | escape }}"
                data-gallery-width="{{ image.width }}" data-gallery-height="{{ image.height }}">
