<script data-product-gallery-script>
(() => {
  const root = document.getElementById('ProductMain-{{ section.id }}');
  const gallery = root?.querySelector('[data-product-gallery]');
  const main = gallery?.querySelector('#MainProductImg');
  if (!main) return;
  const buttons = [...gallery.querySelectorAll('button[data-gallery-src]')];
  const identity = src => {
    try { return new URL(src, document.baseURI).pathname; } catch { return src; }
  };
  const markSelected = src => {
    let selected = false;
    buttons.forEach(button => {
      const active = !selected && identity(button.dataset.gallerySrc) === identity(src);
      selected ||= active;
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-pressed', String(active));
    });
  };
  const showImage = image => {
    if (!image?.src) return;
    main.src = image.src;
    if (typeof image.alt === 'string') main.alt = image.alt;
    for (const dimension of ['width', 'height']) {
      if (Number(image[dimension]) > 0) main.setAttribute(dimension, image[dimension]);
    }
    markSelected(image.src);
  };
  gallery.addEventListener('click', event => {
    const button = event.target.closest('button[data-gallery-src]');
    if (!button || !gallery.contains(button)) return;
    showImage({src: button.dataset.gallerySrc, alt: button.dataset.galleryAlt,
      width: button.dataset.galleryWidth, height: button.dataset.galleryHeight});
  });
  gallery.addEventListener('equipro:gallery-image', event => showImage(event.detail));
  markSelected(main.getAttribute('src'));
})();
</script>

<script>
  const productVariants = JSON.parse(document.getElementById('ProductVariantsJson-{{ target_product.id }}').textContent);

  document.querySelectorAll('#ProductMain-{{ section.id }} [data-js-product-controls]').forEach(element => { element.hidden = false; });
  const purchaseForm = document.querySelector('#ProductMain-{{ section.id }} form[action*="/cart/add"]');
  if (purchaseForm) purchaseForm.addEventListener('submit', event => {
    const variant = productVariants.find(item => String(item.id) === String(purchaseForm.querySelector('[name="id"]')?.value));
    if (!variant || !variant.available || !variant.purchasable) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }, true);

  document.querySelectorAll('.product-variant-selector').forEach(select => {
    select.addEventListener('change', updateSelectedVariant);
  });

  function selectSwatch(btn) {
    const optionIndex = btn.dataset.optionIndex;
    const value = btn.dataset.value;

    const targetSelect = document.querySelector(`.product-variant-selector[data-option-index="${optionIndex}"]`);

    if (targetSelect) {
      targetSelect.value = value;
      targetSelect.dispatchEvent(new Event('change', { bubbles: true }));
    }
  }

  function updateSelectedVariant() {
    const selectors = document.querySelectorAll('.product-variant-selector');
    const selectedValues = {{ current_variant.options | json }} || [];
    selectors.forEach(select => { selectedValues[Number(select.dataset.optionIndex)] = select.value; });

    const matchedVariant = productVariants.find(variant => {
      return selectedValues.every((val, index) => variant.options[index] === val);
    });

    document.querySelectorAll('#ProductMain-{{ section.id }} .product-swatch-btn').forEach(swatch => {
      const active = Boolean(matchedVariant && matchedVariant.options[Number(swatch.dataset.optionIndex)] === swatch.dataset.value);
      swatch.classList.toggle('is-active', active);
      swatch.setAttribute('aria-pressed', String(active));
    });

    if (!matchedVariant) {
      const variantIdInput = document.getElementById('ProductVariantIdInput');
      if (variantIdInput) variantIdInput.value = '';
      const cartBtn = document.getElementById('AddToCartButton');
      if (cartBtn) { cartBtn.disabled = true; cartBtn.textContent = 'UNAVAILABLE'; }
      purchaseForm?.closest('equipro-product-form')?.sync?.(null);
      return;
    }
    if (matchedVariant) {
      const variantIdInput = document.getElementById('ProductVariantIdInput');
      if (variantIdInput) variantIdInput.value = matchedVariant.available && matchedVariant.purchasable ? matchedVariant.id : '';

      const priceContainer = document.getElementById('ProductPriceContainer');
      if (priceContainer) priceContainer.textContent = matchedVariant.price;

      const cartBtn = document.getElementById('AddToCartButton');
      if (cartBtn) {
        if (!matchedVariant.purchasable) {
          cartBtn.disabled = true;
          cartBtn.textContent = {{ 'products.purchase_unavailable' | t | json }};
        } else if (matchedVariant.available) {
          cartBtn.disabled = false;
          cartBtn.textContent = {{ section.settings.btn_label | default: 'ADD TO CART' | json }};
        } else {
          cartBtn.disabled = true;
          cartBtn.textContent = "OUT OF STOCK";
        }
      }

      if (matchedVariant.image) {
        const gallery = document.getElementById('ProductMain-{{ section.id }}')?.querySelector?.('[data-product-gallery]');
        gallery?.dispatchEvent(new CustomEvent('equipro:gallery-image', {
          detail: {src: matchedVariant.image, ...matchedVariant.image_metadata}
        }));
      }
    }
    purchaseForm?.closest('equipro-product-form')?.sync?.(matchedVariant);
  }

  function adjustQty(val) {
    const input = document.getElementById('QuantityInput');
    if (!input) return;
    let current = parseInt(input.value) || 1;
    current += val;
    if (current < 1) current = 1;
    input.value = current;
  }
</script>

{% comment %}
  R2.0 STOCK DIAGNOSTIC — TEST THEME ONLY
  Read-only diagnostic, visible only when ?equipro_stock_debug=1.
  No changes to product forms, inventory, pricing or cart requests.
{% endcomment %}
<script>
(() => {
  if (new URLSearchParams(window.location.search).get('equipro_stock_debug') !== '1') return;
  const root = document.getElementById('ProductMain-{{ section.id }}');
  if (!root || root.querySelector('[data-equipro-stock-debug]')) return;
  const box = root.querySelector('.product-buy-box');
  if (!box) return;
  const panel = document.createElement('details');
  panel.open = true;
  panel.setAttribute('data-equipro-stock-debug', '');
  panel.style.cssText = 'margin-top:16px;padding:12px;border:2px solid #ab273b;border-radius:8px;background:#fff;color:#111;max-width:100%;';
  const heading = document.createElement('summary');
  heading.textContent = 'Equipro test: stock diagnostic (read-only)';
  heading.style.fontWeight = 'bold';
  const output = document.createElement('pre');
  output.style.cssText = 'white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.5;';
  panel.append(heading, output);
  box.appendChild(panel);
  function render() {
    const button = root.querySelector('#AddToCartButton');
    const input = root.querySelector('#ProductVariantIdInput');
    const script = document.getElementById('ProductVariantsJson-{{ target_product.id }}');
    let variants = [], parseError = '';
    try { variants = JSON.parse(script?.textContent || '[]'); } catch (e) { parseError = String(e); }
    const current = variants.find(v => String(v.id) === String(input?.value));
    const initial = variants.find(v => String(v.id) === String({{ current_variant.id | json }}));
    const fields = {
      'Liquid product': {{ target_product.id | json }},
      'Liquid initial variant': {{ current_variant.id | json }},
      'Liquid initial available': {{ current_variant.available | json }},
      'Liquid initial inventory quantity': {{ current_variant.inventory_quantity | json }},
      'Liquid initial inventory policy': {{ current_variant.inventory_policy | json }},
      'Liquid initial price cents': {{ current_variant.price | json }},
      'JSON initial available': initial?.available ?? 'not found',
      'JSON initial purchasable': initial?.purchasable ?? 'not found',
      'Form selected variant id': input?.value || '(empty)',
      'Form variant available': current?.available ?? 'not found',
      'Form variant purchasable': current?.purchasable ?? 'not found',
      'Button text': button?.textContent?.trim() || '(missing)',
      'Button disabled': button?.disabled ?? 'missing',
      'Selected size / color': [...root.querySelectorAll('.product-variant-selector')].map(s => s.value).join(' / ') || '(default)',
      'Variant data parse error': parseError || '(none)'
    };
    output.textContent = Object.entries(fields).map(([k,v]) => k + ': ' + String(v)).join('\n');
  }
  render();
  setTimeout(render, 500);
  root.addEventListener('change', () => setTimeout(render, 0));
})();
</script>

