/* CUSTOM SPA PACK BUILDER - APPLE STATIC GRID LAYOUT */

.spa-pack-section {
    padding: 60px 0;
    background-color: #f5f5f7;
  }

  /* APPLE PILL CAPSULE BAR CONTAINER */
  .spa-pack-pill-wrapper {
    margin-bottom: 36px;
    display: flex;
    justify-content: flex-start;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .spa-pack-pill-wrapper::-webkit-scrollbar {
    display: none;
  }

  .spa-pack-pill-bar {
    display: inline-flex;
    align-items: center;
    background-color: #e8e8ed;
    padding: 5px;
    border-radius: 980px;
    gap: 4px;
  }

  .spa-pack-pill-item {
    background: transparent;
    border: none;
    font-size: 0.88rem;
    font-weight: 500;
    color: #515154;
    padding: 9px 20px;
    border-radius: 980px;
    cursor: pointer;
    transition: all 0.25s cubic-bezier(0.25, 0.1, 0.25, 1);
    white-space: nowrap;
  }

  .spa-pack-pill-item:hover {
    color: #1d1d1f;
  }

  .spa-pack-pill-item.is-active {
    background-color: #ab273b; /* Equipro Red Active Pill */
    color: #ffffff;
    font-weight: 600;
    box-shadow: 0 2px 10px rgba(171, 39, 59, 0.25);
  }

  /* TAB PANELS CONTROL */
  .spa-pack-panel {
    display: none;
  }

  .spa-pack-panel.is-active {
    display: block;
  }

  /* STATIC CSS GRID (MATCHING APPLE SCREENSHOT) */
  .spa-pack-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
  }

  @media (max-width: 1024px) {
    .spa-pack-grid {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media (max-width: 640px) {
    .spa-pack-grid {
      grid-template-columns: 1fr;
    }
  }

  /* HERO PROMO CARD (SPANS 2 COLUMNS IN DESKTOP GRID) */
  .spa-pack-hero-card {
    grid-column: span 2;
    border-radius: 24px;
    padding: 36px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    overflow: hidden;
    position: relative;
    min-height: 380px;
  }

  @media (max-width: 1024px) {
    .spa-pack-hero-card {
      grid-column: span 2;
    }
  }

  @media (max-width: 640px) {
    .spa-pack-hero-card {
      grid-column: span 1;
    }
  }

  .spa-pack-hero-card__title {
    font-size: 2.2rem;
    font-weight: 700;
    line-height: 1.15;
    margin: 0 0 12px 0;
    letter-spacing: -0.02em;
  }

  .spa-pack-section .spa-pack-hero-card__title {
    color: inherit;
  }

  .spa-pack-hero-card__subtitle {
    font-size: 0.95rem;
    opacity: 0.85;
    line-height: 1.4;
    margin: 0;
    max-width: 380px;
  }

  .spa-pack-hero-card__image-wrapper {
    margin-top: 20px;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: flex-end;
  }

  .spa-pack-hero-card__image {
    max-width: 100%;
    max-height: 220px;
    object-fit: contain;
  }

  /* WHITE PRODUCT CARDS */
  .spa-pack-card {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
    text-decoration: none;
    color: inherit;
    width: 100%;
    height: 100%;
    background: #ffffff;
    border-radius: 20px;
    padding: 20px;
    box-shadow: 0 2px 16px rgba(0, 0, 0, 0.03);
    transition: transform 0.25s ease, box-shadow 0.25s ease;
  }

  .spa-pack-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.06);
  }

  .spa-pack-card__image-container {
    position: relative;
    width: 100%;
    aspect-ratio: 4 / 5;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 12px;
    overflow: hidden;
    background-color: #ffffff;
  }

  .spa-pack-card__image {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    transition: opacity 0.35s ease, transform 0.35s ease;
  }

  .spa-pack-card__image--secondary {
    position: absolute;
    inset: 0;
    margin: auto;
    opacity: 0;
  }

  .spa-pack-card:hover .spa-pack-card__image--primary {
    opacity: 0;
  }

  .spa-pack-card:hover .spa-pack-card__image--secondary {
    opacity: 1;
    transform: scale(1.04);
  }

  .spa-pack-card__placeholder {
    width: 50%;
    height: 50%;
    fill: #86868b;
  }

  /* CONTENT DETAILS */
  .spa-pack-card__content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
    margin-top: 16px;
    flex-grow: 1;
  }

  .spa-pack-card__tag {
    font-size: 0.72rem;
    font-weight: 600;
    color: #ab273b;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 4px;
  }

  .spa-pack-card__title {
    font-size: 1.05rem;
    font-weight: 600;
    color: #1d1d1f !important;
    margin: 0 0 12px 0;
    line-height: 1.3;
    letter-spacing: -0.01em;
  }

  .spa-pack-card__price {
    font-size: 0.9rem;
    font-weight: 600;
    color: #1d1d1f;
    margin-top: auto;
    margin-bottom: 0;
  }
/* Profile enhancements stay scoped: this stylesheet is also used by product pages. */
.spa-pack-section .spa-pack-pill-wrapper { padding: 4px; }
.spa-pack-section .spa-pack-pill-bar { flex: 0 0 auto; }
.spa-pack-section .spa-pack-panel[hidden] { display: none; }
.spa-pack-section .spa-pack-grid { min-width: 0; }
.spa-pack-section .spa-pack-card { box-sizing: border-box; min-width: 0; }
.spa-pack-section .spa-pack-card__content { overflow-wrap: anywhere; }
.spa-pack-section .spa-pack-profile-collections { list-style: none; padding: 0; margin: 16px 0 0; }
.spa-pack-section .spa-pack-profile-collections li + li { margin-top: 8px; }
.spa-pack-section .spa-pack-profile-collections a { color: inherit; text-decoration: underline; }
.spa-pack-section .spa-pack-hero-card__subtitle + .spa-pack-hero-card__subtitle { margin-top: 12px; }
.spa-pack-section .spa-pack-explore-all { display: inline-block; margin: -16px 0 24px; color: #ab273b; }
.spa-pack-section :is(.spa-pack-pill-item, a, .spa-pack-panel):focus-visible { outline: 3px solid #ab273b; outline-offset: 2px; }
.spa-pack-section .spa-pack-card:not(.spa-pack-card--has-secondary):hover .spa-pack-card__image--primary { opacity: 1; }
@media (max-width: 640px) {
  .spa-pack-section .spa-pack-pill-item { font-size: .82rem; padding: 9px 14px; }
}
@media (prefers-reduced-motion: reduce) {
  .spa-pack-section :is(.spa-pack-pill-item, .spa-pack-card, .spa-pack-card__image) { transition: none; transform: none; }
}
